Chapter: Nine days

The paragraph: In June the share price fell from 104.5 euros to 1.28 euros. Nobody could stop it.

This graphic covers: The share price fell from 104.5 euros to 1.28 euros.
Length: 5.0 s

Words spoken in it, from its start:
0.3 s  Acme
0.8 s  was
1.3 s  the
1.8 s  name
2.3 s  on
2.8 s  every
3.3 s  door.

Intent: Acme was the name on every door.
Rests on claims: 4

A passing design of this technique (logo-reveal: a mark revealed from a split, its name settling beneath it), in this sandbox and on the tokens, to pattern on. Its words and figures are its own; yours come from this slot and its claims:
````jsx
// Logo reveal: on "Acme" the lockup (the mark, its name beneath) closes in
// from a split over motion.ms.reveal, its two halves meeting at the centre
// where a seam flashes once. The name's tracking then settles over motion.ms.move
// while the rest of the line builds beneath, word by word as it is spoken, and
// the lockup holds.
// The mark is drawn only when props.logos holds it; the name always shows, so a missing mark still reads.
// The mark fits a box of its own in both directions, so a square or tall mark fits as a wide one does,
// and the name is sized from its length, so "Deutsche Bank" fits the 9:16 frame as "Acme" does.
const NAME = 'Acme'

// Where the narration says the name: the index of the word that starts it, or -1.
function nameIndex(words) {
  return words.findIndex((word) => word.text.indexOf(NAME.split(' ')[0]) === 0)
}

// A helper, called directly: 0 to 1 over lengthMs from atMs on the arrival curve, held at 1.
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(
    frame, [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)], [0, 1],
    { easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp' },
  )
}

// A helper, called directly: the lockup, the mark at its own aspect ratio over the name.
function lockup(spec) {
  const { colors, fonts } = spec.brand
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: spec.gap }}>
      {spec.mark ? (
        <Remotion.Img src={spec.mark.src} style={{ width: spec.markWidth, height: spec.markHeight }} />
      ) : null}
      <div
        style={{
          fontFamily: fonts.heading, fontSize: spec.nameSize, lineHeight: 1.1,
          letterSpacing: spec.tracking + 'em', color: colors.textPrimary, whiteSpace: 'nowrap',
        }}
      >
        {NAME}
      </div>
    </div>
  )
}

// A helper, called directly: one half of the lockup, clipped to its side and closing in from the split.
function halfOf(side, spec, open, reveal) {
  const shift = (side === 'left' ? -1 : 1) * spec.split * (1 - reveal)
  return (
    <div
      key={side}
      style={{
        position: 'absolute', top: 0, left: 0, width: '100%', height: '100%',
        display: 'flex', justifyContent: 'center', opacity: reveal,
        clipPath: side === 'left' ? 'inset(0 50% 0 0)' : 'inset(0 0 0 50%)',
        transform: 'translateX(' + shift + 'px)',
      }}
    >
      {open}
    </div>
  )
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors, fonts } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080

  const mark = props.logos ? props.logos[NAME] : undefined
  const roomW = width - inset.left - inset.right
  const roomH = height - inset.top - inset.bottom
  // The mark's box: at most this wide and this tall; the mark keeps its aspect ratio inside it.
  const maxW = Math.min(roomW, (portrait ? 760 : 720) * unit)
  const maxH = (portrait ? 0.28 : 0.34) * roomH
  const fit = mark ? Math.min(maxW / mark.width, maxH / mark.height) : 0
  const markWidth = mark ? mark.width * fit : 0
  const markHeight = mark ? mark.height * fit : 0
  // The name on one line: about 0.62 em a character plus the widest tracking, within the room.
  const nameSize = Math.min((mark ? 110 : 180) * unit, (0.9 * roomW) / (NAME.length * (0.62 + 0.12)))
  const gap = mark ? 36 * unit : 0
  const boxHeight = markHeight + gap + nameSize * 1.1

  const said = nameIndex(props.words)
  const nameAt = said >= 0 ? props.words[said].atMs : 300
  const metAt = nameAt + motion.ms.reveal
  const reveal = arrive(frame, fps, nameAt, motion.ms.reveal)
  // The seam flashes once as the halves meet: up on the arrival curve, away on the exit curve.
  const seam = Remotion.interpolate(
    frame,
    [motion.frames(nameAt + motion.ms.reveal * 0.6, fps), motion.frames(metAt, fps), motion.frames(metAt + motion.ms.exit, fps)],
    [0, 0.85, 0],
    { easing: [motion.ease.enter, motion.ease.exit], extrapolateLeft: 'clamp', extrapolateRight: 'clamp' },
  )
  // After the meeting the name's tracking settles, a move over motion.ms.move; the words after it keep the change going.
  const tracking = Remotion.interpolate(
    frame, [motion.frames(metAt, fps), motion.frames(metAt + motion.ms.move, fps)], [0.12, 0.04],
    { easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp' },
  )
  const spec = {
    brand: props.brand, mark: mark, markWidth: markWidth, markHeight: markHeight,
    nameSize: nameSize, gap: gap, tracking: tracking, split: 0.08 * maxW,
  }
  // The line beneath is what is said after the name, all of its words ("Deutsche Bank" is two).
  const line = said >= 0 ? props.words.slice(said + NAME.split(' ').length) : props.words.filter((word) => word.atMs > nameAt)

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        justifyContent: 'center', alignItems: 'center', gap: 56 * unit,
      }}
    >
      <div style={{ position: 'relative', width: roomW, height: boxHeight }}>
        {halfOf('left', spec, lockup(spec), reveal)}
        {halfOf('right', spec, lockup(spec), reveal)}
        <div
          style={{
            position: 'absolute', top: 0, left: '50%', width: 3 * unit, height: '100%',
            transform: 'translateX(-50%)', backgroundColor: colors.accent, opacity: seam,
          }}
        />
      </div>
      <div style={{ fontFamily: fonts.title, fontSize: 48 * unit, color: colors.textSecondary, textAlign: 'center' }}>
        {line.map((word) => {
          const enter = arrive(frame, fps, word.atMs, motion.ms.enter)
          return (
            <span
              key={word.atMs}
              style={{
                display: 'inline-block', marginRight: '0.25em', opacity: enter,
                transform: 'translateY(' + (1 - enter) * motion.px.rise * unit + 'px)',
              }}
            >
              {word.text}
            </span>
          )
        })}
      </div>
    </Remotion.AbsoluteFill>
  )
}

````
